/**
 * V3 Lexer (어휘 분석기)
 *
 * V3 소스 코드를 토큰으로 변환
 * - V3 키워드 인식 (ARR, INT, STR, IF, FOR 등)
 * - Python 스타일 들여쓰기 (INDENT/DEDENT)
 * - 에러 위치 추적
 */

export enum V3TokenType {
  // 리터럴
  NUMBER = 'NUMBER',
  STRING = 'STRING',
  BOOL = 'BOOL',

  // 식별자 & 키워드
  IDENTIFIER = 'IDENTIFIER',
  KEYWORD = 'KEYWORD',

  // 연산자
  PLUS = 'PLUS',
  MINUS = 'MINUS',
  STAR = 'STAR',
  SLASH = 'SLASH',
  EQ = 'EQ',
  NE = 'NE',
  LT = 'LT',
  LE = 'LE',
  GT = 'GT',
  GE = 'GE',
  ASSIGN = 'ASSIGN',
  AND = 'AND',
  OR = 'OR',

  // 기호
  LPAREN = 'LPAREN',      // (
  RPAREN = 'RPAREN',      // )
  LBRACKET = 'LBRACKET',  // [
  RBRACKET = 'RBRACKET',  // ]
  COLON = 'COLON',        // :
  COMMA = 'COMMA',        // ,
  ARROW = 'ARROW',        // ->
  DOT = 'DOT',            // .

  // 특수
  INDENT = 'INDENT',
  DEDENT = 'DEDENT',
  NEWLINE = 'NEWLINE',
  EOF = 'EOF',
  COMMENT = 'COMMENT',
}

export interface V3Token {
  type: V3TokenType;
  value: any;
  line: number;
  column: number;
  raw: string;
}

const V3_KEYWORDS = new Set([
  // 타입
  'ARR', 'INT', 'STR', 'BOOL', 'FLOAT',

  // 배열 연산
  'ARR_SUM', 'ARR_AVG', 'ARR_MAX', 'ARR_MIN', 'ARR_LEN',
  'ARR_PUSH', 'ARR_GET', 'ARR_SET', 'ARR_MAP', 'ARR_FILTER',

  // 제어흐름
  'IF', 'ELSE', 'FOR', 'IN', 'WHILE', 'BREAK', 'CONTINUE',

  // 함수
  'FUNC', 'RETURN', 'CALL',

  // 기타
  'TRUE', 'FALSE', 'NONE', 'PRINTLN', 'INPUT',
]);

export class V3Lexer {
  private source: string;
  private pos: number = 0;
  private line: number = 1;
  private column: number = 1;
  private tokens: V3Token[] = [];
  private indentStack: number[] = [0];
  private pendingDedents: number = 0;
  private lineStart: boolean = true;

  constructor(source: string) {
    this.source = source;
  }

  tokenize(): V3Token[] {
    while (this.pos < this.source.length) {
      this.skipWhitespaceOnLine();

      if (this.isNewline()) {
        this.consumeNewline();
        this.lineStart = true;
        continue;
      }

      if (this.isComment()) {
        this.skipComment();
        continue;
      }

      // 줄 시작: 들여쓰기 처리
      if (this.lineStart && !this.isNewline()) {
        this.handleIndentation();
        this.lineStart = false;
      }

      if (this.pos >= this.source.length) break;

      const ch = this.peek();

      // 문자열
      if (ch === '"' || ch === "'") {
        this.consumeString();
        continue;
      }

      // 숫자
      if (this.isDigit(ch)) {
        this.consumeNumber();
        continue;
      }

      // 식별자 또는 키워드
      if (this.isLetter(ch) || ch === '_') {
        this.consumeIdentifierOrKeyword();
        continue;
      }

      // 연산자 및 기호
      if (!this.consumeOperatorOrSymbol()) {
        throw new Error(`미인식 문자 '${ch}' at line ${this.line}, column ${this.column}`);
      }
    }

    // 파일 끝: DEDENT 생성
    while (this.indentStack.length > 1) {
      this.indentStack.pop();
      this.addToken(V3TokenType.DEDENT, null);
    }

    this.addToken(V3TokenType.EOF, null);
    return this.tokens;
  }

  private handleIndentation(): void {
    let spaces = 0;
    while (this.pos < this.source.length && this.peek() === ' ') {
      spaces++;
      this.pos++;
      this.column++;
    }

    const currentIndent = this.indentStack[this.indentStack.length - 1];

    if (spaces > currentIndent) {
      this.indentStack.push(spaces);
      this.addToken(V3TokenType.INDENT, null);
    } else if (spaces < currentIndent) {
      while (this.indentStack.length > 1 && this.indentStack[this.indentStack.length - 1] > spaces) {
        this.indentStack.pop();
        this.addToken(V3TokenType.DEDENT, null);
      }
    }
  }

  private consumeString(): void {
    const quote = this.peek();
    const startLine = this.line;
    const startCol = this.column;
    this.pos++;
    this.column++;

    let value = '';
    while (this.pos < this.source.length && this.peek() !== quote) {
      if (this.peek() === '\\' && this.peekNext() === quote) {
        this.pos += 2;
        this.column += 2;
        value += quote;
      } else if (this.peek() === '\\' && this.peekNext() === 'n') {
        this.pos += 2;
        this.column += 2;
        value += '\n';
      } else {
        value += this.peek();
        this.pos++;
        this.column++;
      }
    }

    if (this.pos >= this.source.length) {
      throw new Error(`닫히지 않은 문자열 at line ${startLine}, column ${startCol}`);
    }

    this.pos++;
    this.column++;
    this.addToken(V3TokenType.STRING, value);
  }

  private consumeNumber(): void {
    let value = '';
    while (this.pos < this.source.length && this.isDigit(this.peek())) {
      value += this.peek();
      this.pos++;
      this.column++;
    }

    if (this.peek() === '.' && this.isDigit(this.peekNext())) {
      value += '.';
      this.pos++;
      this.column++;
      while (this.pos < this.source.length && this.isDigit(this.peek())) {
        value += this.peek();
        this.pos++;
        this.column++;
      }
    }

    this.addToken(V3TokenType.NUMBER, parseFloat(value));
  }

  private consumeIdentifierOrKeyword(): void {
    let value = '';
    while (
      this.pos < this.source.length &&
      (this.isLetter(this.peek()) || this.isDigit(this.peek()) || this.peek() === '_')
    ) {
      value += this.peek();
      this.pos++;
      this.column++;
    }

    if (V3_KEYWORDS.has(value)) {
      if (value === 'TRUE') {
        this.addToken(V3TokenType.BOOL, true);
      } else if (value === 'FALSE') {
        this.addToken(V3TokenType.BOOL, false);
      } else {
        this.addToken(V3TokenType.KEYWORD, value);
      }
    } else {
      this.addToken(V3TokenType.IDENTIFIER, value);
    }
  }

  private consumeOperatorOrSymbol(): boolean {
    const ch = this.peek();
    const next = this.peekNext();

    // 2글자 연산자
    if (ch === '-' && next === '>') {
      this.pos += 2;
      this.column += 2;
      this.addToken(V3TokenType.ARROW, '->');
      return true;
    }

    if (ch === '=' && next === '=') {
      this.pos += 2;
      this.column += 2;
      this.addToken(V3TokenType.EQ, '==');
      return true;
    }

    if (ch === '!' && next === '=') {
      this.pos += 2;
      this.column += 2;
      this.addToken(V3TokenType.NE, '!=');
      return true;
    }

    if (ch === '<' && next === '=') {
      this.pos += 2;
      this.column += 2;
      this.addToken(V3TokenType.LE, '<=');
      return true;
    }

    if (ch === '>' && next === '=') {
      this.pos += 2;
      this.column += 2;
      this.addToken(V3TokenType.GE, '>=');
      return true;
    }

    // 1글자 연산자
    const singleCharTokens: { [key: string]: V3TokenType } = {
      '+': V3TokenType.PLUS,
      '-': V3TokenType.MINUS,
      '*': V3TokenType.STAR,
      '/': V3TokenType.SLASH,
      '=': V3TokenType.ASSIGN,
      '<': V3TokenType.LT,
      '>': V3TokenType.GT,
      '(': V3TokenType.LPAREN,
      ')': V3TokenType.RPAREN,
      '[': V3TokenType.LBRACKET,
      ']': V3TokenType.RBRACKET,
      ':': V3TokenType.COLON,
      ',': V3TokenType.COMMA,
      '.': V3TokenType.DOT,
    };

    if (singleCharTokens[ch]) {
      this.addToken(singleCharTokens[ch], ch);
      this.pos++;
      this.column++;
      return true;
    }

    return false;
  }

  private skipWhitespaceOnLine(): void {
    while (this.pos < this.source.length && this.peek() === ' ') {
      this.pos++;
      this.column++;
    }
  }

  private skipComment(): void {
    if (this.peek() === '#') {
      while (this.pos < this.source.length && !this.isNewline()) {
        this.pos++;
        this.column++;
      }
    }
  }

  private consumeNewline(): void {
    if (this.peek() === '\r' && this.peekNext() === '\n') {
      this.pos += 2;
    } else {
      this.pos++;
    }
    this.line++;
    this.column = 1;
    this.addToken(V3TokenType.NEWLINE, '\n');
  }

  private isNewline(): boolean {
    return this.peek() === '\n' || (this.peek() === '\r' && this.peekNext() === '\n');
  }

  private isComment(): boolean {
    return this.peek() === '#';
  }

  private isDigit(ch: string): boolean {
    return ch >= '0' && ch <= '9';
  }

  private isLetter(ch: string): boolean {
    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
  }

  private peek(): string {
    return this.pos < this.source.length ? this.source[this.pos] : '\0';
  }

  private peekNext(): string {
    return this.pos + 1 < this.source.length ? this.source[this.pos + 1] : '\0';
  }

  private addToken(type: V3TokenType, value: any): void {
    this.tokens.push({
      type,
      value,
      line: this.line,
      column: this.column,
      raw: value?.toString() || '',
    });
  }
}

