/**
 * V3 Parser (구문 분석기)
 *
 * 토큰 → AST (Abstract Syntax Tree) 변환
 */

import { V3Token, V3TokenType, V3Lexer } from './v3-lexer';

export interface V3ASTNode {
  type: string;
  line: number;
  column: number;
}

export interface V3Program extends V3ASTNode {
  type: 'Program';
  statements: V3Statement[];
}

export type V3Statement = V3VarDecl | V3IfStmt | V3ForLoop | V3FuncDecl | V3ExprStmt | V3ReturnStmt;

export interface V3VarDecl extends V3ASTNode {
  type: 'VarDecl';
  varType: 'ARR' | 'INT' | 'STR' | 'BOOL' | 'FLOAT';
  name: string;
  value: V3Expr;
}

export interface V3IfStmt extends V3ASTNode {
  type: 'IfStmt';
  condition: V3Expr;
  thenBlock: V3Statement[];
  elseBlock?: V3Statement[];
}

export interface V3ForLoop extends V3ASTNode {
  type: 'ForLoop';
  variable: string;
  iterable: V3Expr;
  body: V3Statement[];
}

export interface V3FuncDecl extends V3ASTNode {
  type: 'FuncDecl';
  name: string;
  params: Array<{ name: string; type: string }>;
  returnType: string;
  body: V3Statement[];
}

export interface V3ExprStmt extends V3ASTNode {
  type: 'ExprStmt';
  expr: V3Expr;
}

export interface V3ReturnStmt extends V3ASTNode {
  type: 'ReturnStmt';
  value?: V3Expr;
}

export type V3Expr =
  | V3Number
  | V3String
  | V3Bool
  | V3Identifier
  | V3BinaryOp
  | V3UnaryOp
  | V3ArrayLiteral
  | V3ArrayAccess
  | V3ArrayOp
  | V3FuncCall
  | V3Assignment;

export interface V3Number extends V3ASTNode {
  type: 'Number';
  value: number;
}

export interface V3String extends V3ASTNode {
  type: 'String';
  value: string;
}

export interface V3Bool extends V3ASTNode {
  type: 'Bool';
  value: boolean;
}

export interface V3Identifier extends V3ASTNode {
  type: 'Identifier';
  name: string;
}

export interface V3BinaryOp extends V3ASTNode {
  type: 'BinaryOp';
  left: V3Expr;
  op: string;
  right: V3Expr;
}

export interface V3UnaryOp extends V3ASTNode {
  type: 'UnaryOp';
  op: string;
  operand: V3Expr;
}

export interface V3ArrayLiteral extends V3ASTNode {
  type: 'ArrayLiteral';
  elements: V3Expr[];
}

export interface V3ArrayAccess extends V3ASTNode {
  type: 'ArrayAccess';
  array: V3Expr;
  index: V3Expr;
}

export interface V3ArrayOp extends V3ASTNode {
  type: 'ArrayOp';
  op: 'ARR_SUM' | 'ARR_AVG' | 'ARR_MAX' | 'ARR_MIN' | 'ARR_LEN' | 'ARR_MAP' | 'ARR_FILTER';
  array: V3Expr;
  callback?: V3Expr;
}

export interface V3FuncCall extends V3ASTNode {
  type: 'FuncCall';
  name: string;
  args: V3Expr[];
}

export interface V3Assignment extends V3ASTNode {
  type: 'Assignment';
  name: string;
  value: V3Expr;
}

export class V3Parser {
  private tokens: V3Token[];
  private pos: number = 0;

  constructor(source: string) {
    const lexer = new V3Lexer(source);
    this.tokens = lexer.tokenize();
  }

  parse(): V3Program {
    const statements: V3Statement[] = [];

    while (!this.isAtEnd()) {
      if (this.check(V3TokenType.NEWLINE)) {
        this.advance();
        continue;
      }
      statements.push(this.parseStatement());
    }

    return {
      type: 'Program',
      statements,
      line: 1,
      column: 1,
    };
  }

  private parseStatement(): V3Statement {
    const token = this.peek();

    // 변수 선언
    if (this.isType(token)) {
      return this.parseVarDecl();
    }

    // IF 문
    if (this.match(V3TokenType.KEYWORD, 'IF')) {
      return this.parseIfStmt();
    }

    // FOR 루프
    if (this.match(V3TokenType.KEYWORD, 'FOR')) {
      return this.parseForLoop();
    }

    // 함수 선언
    if (this.match(V3TokenType.KEYWORD, 'FUNC')) {
      return this.parseFuncDecl();
    }

    // RETURN
    if (this.match(V3TokenType.KEYWORD, 'RETURN')) {
      const returnStmt: V3ReturnStmt = {
        type: 'ReturnStmt',
        value: this.check(V3TokenType.NEWLINE) ? undefined : this.parseExpr(),
        line: token.line,
        column: token.column,
      };
      this.consumeNewline();
      return returnStmt;
    }

    // 표현식 문
    const expr = this.parseExpr();
    this.consumeNewline();
    return {
      type: 'ExprStmt',
      expr,
      line: token.line,
      column: token.column,
    };
  }

  private parseVarDecl(): V3VarDecl {
    const token = this.peek();
    const varType = this.advance().value;
    const name = this.consume(V3TokenType.IDENTIFIER, '변수명 필요').value;
    this.consume(V3TokenType.ASSIGN, '= 필요');
    const value = this.parseExpr();
    this.consumeNewline();

    return {
      type: 'VarDecl',
      varType,
      name,
      value,
      line: token.line,
      column: token.column,
    };
  }

  private parseIfStmt(): V3IfStmt {
    const token = this.peek();
    const condition = this.parseExpr();
    this.consume(V3TokenType.COLON, ': 필요');
    this.consumeNewline();

    const thenBlock = this.parseBlock();

    let elseBlock: V3Statement[] | undefined;
    if (this.check(V3TokenType.KEYWORD) && this.peekValue() === 'ELSE') {
      this.advance();
      this.consume(V3TokenType.COLON, ': 필요');
      this.consumeNewline();
      elseBlock = this.parseBlock();
    }

    return {
      type: 'IfStmt',
      condition,
      thenBlock,
      elseBlock,
      line: token.line,
      column: token.column,
    };
  }

  private parseForLoop(): V3ForLoop {
    const token = this.peek();
    const variable = this.consume(V3TokenType.IDENTIFIER, '변수명 필요').value;
    this.consume(V3TokenType.KEYWORD, 'IN 필요', 'IN');
    const iterable = this.parseExpr();
    this.consume(V3TokenType.COLON, ': 필요');
    this.consumeNewline();

    const body = this.parseBlock();

    return {
      type: 'ForLoop',
      variable,
      iterable,
      body,
      line: token.line,
      column: token.column,
    };
  }

  private parseFuncDecl(): V3FuncDecl {
    const token = this.peek();
    const name = this.consume(V3TokenType.IDENTIFIER, '함수명 필요').value;
    this.consume(V3TokenType.LPAREN, '( 필요');

    const params: Array<{ name: string; type: string }> = [];
    while (!this.check(V3TokenType.RPAREN)) {
      const paramName = this.consume(V3TokenType.IDENTIFIER, '파라미터명 필요').value;
      this.consume(V3TokenType.COLON, ': 필요');
      const paramType = this.consume(V3TokenType.KEYWORD, '타입 필요').value;
      params.push({ name: paramName, type: paramType });

      if (!this.check(V3TokenType.RPAREN)) {
        this.consume(V3TokenType.COMMA, ', 필요');
      }
    }
    this.consume(V3TokenType.RPAREN, ') 필요');

    this.consume(V3TokenType.ARROW, '-> 필요');
    const returnType = this.consume(V3TokenType.KEYWORD, '반환 타입 필요').value;
    this.consume(V3TokenType.COLON, ': 필요');
    this.consumeNewline();

    const body = this.parseBlock();

    return {
      type: 'FuncDecl',
      name,
      params,
      returnType,
      body,
      line: token.line,
      column: token.column,
    };
  }

  private parseBlock(): V3Statement[] {
    const statements: V3Statement[] = [];

    this.consume(V3TokenType.INDENT, 'INDENT 필요');

    while (!this.check(V3TokenType.DEDENT) && !this.isAtEnd()) {
      if (this.check(V3TokenType.NEWLINE)) {
        this.advance();
        continue;
      }
      statements.push(this.parseStatement());
    }

    this.consume(V3TokenType.DEDENT, 'DEDENT 필요');

    return statements;
  }

  private parseExpr(): V3Expr {
    return this.parseAssignmentOrExpr();
  }

  private parseAssignmentOrExpr(): V3Expr {
    let expr = this.parseOr();

    if (this.check(V3TokenType.IDENTIFIER) && this.peekAhead(1)?.type === V3TokenType.ASSIGN) {
      const name = this.advance().value;
      this.advance(); // =
      const value = this.parseExpr();
      return {
        type: 'Assignment',
        name,
        value,
        line: expr.line,
        column: expr.column,
      };
    }

    return expr;
  }

  private parseOr(): V3Expr {
    let expr = this.parseAnd();

    while (this.match(V3TokenType.KEYWORD, 'OR')) {
      const op = this.previous().value;
      const right = this.parseAnd();
      expr = {
        type: 'BinaryOp',
        left: expr,
        op,
        right,
        line: expr.line,
        column: expr.column,
      };
    }

    return expr;
  }

  private parseAnd(): V3Expr {
    let expr = this.parseComparison();

    while (this.match(V3TokenType.KEYWORD, 'AND')) {
      const op = this.previous().value;
      const right = this.parseComparison();
      expr = {
        type: 'BinaryOp',
        left: expr,
        op,
        right,
        line: expr.line,
        column: expr.column,
      };
    }

    return expr;
  }

  private parseComparison(): V3Expr {
    let expr = this.parseAdditive();

    while (
      this.match(V3TokenType.EQ) ||
      this.match(V3TokenType.NE) ||
      this.match(V3TokenType.LT) ||
      this.match(V3TokenType.LE) ||
      this.match(V3TokenType.GT) ||
      this.match(V3TokenType.GE)
    ) {
      const op = this.previous().raw;
      const right = this.parseAdditive();
      expr = {
        type: 'BinaryOp',
        left: expr,
        op,
        right,
        line: expr.line,
        column: expr.column,
      };
    }

    return expr;
  }

  private parseAdditive(): V3Expr {
    let expr = this.parseMultiplicative();

    while (this.match(V3TokenType.PLUS) || this.match(V3TokenType.MINUS)) {
      const op = this.previous().raw;
      const right = this.parseMultiplicative();
      expr = {
        type: 'BinaryOp',
        left: expr,
        op,
        right,
        line: expr.line,
        column: expr.column,
      };
    }

    return expr;
  }

  private parseMultiplicative(): V3Expr {
    let expr = this.parseUnary();

    while (this.match(V3TokenType.STAR) || this.match(V3TokenType.SLASH)) {
      const op = this.previous().raw;
      const right = this.parseUnary();
      expr = {
        type: 'BinaryOp',
        left: expr,
        op,
        right,
        line: expr.line,
        column: expr.column,
      };
    }

    return expr;
  }

  private parseUnary(): V3Expr {
    if (this.match(V3TokenType.MINUS)) {
      const op = this.previous().raw;
      const expr = this.parseUnary();
      return {
        type: 'UnaryOp',
        op,
        operand: expr,
        line: expr.line,
        column: expr.column,
      };
    }

    return this.parsePostfix();
  }

  private parsePostfix(): V3Expr {
    let expr = this.parsePrimary();

    while (true) {
      if (this.match(V3TokenType.LBRACKET)) {
        const index = this.parseExpr();
        this.consume(V3TokenType.RBRACKET, '] 필요');
        expr = {
          type: 'ArrayAccess',
          array: expr,
          index,
          line: expr.line,
          column: expr.column,
        };
      } else if (this.match(V3TokenType.LPAREN) && expr.type === 'Identifier') {
        const args: V3Expr[] = [];
        while (!this.check(V3TokenType.RPAREN)) {
          args.push(this.parseExpr());
          if (!this.check(V3TokenType.RPAREN)) {
            this.consume(V3TokenType.COMMA, ', 필요');
          }
        }
        this.consume(V3TokenType.RPAREN, ') 필요');
        expr = {
          type: 'FuncCall',
          name: (expr as V3Identifier).name,
          args,
          line: expr.line,
          column: expr.column,
        };
      } else {
        break;
      }
    }

    return expr;
  }

  private parsePrimary(): V3Expr {
    const token = this.peek();

    // 숫자
    if (this.match(V3TokenType.NUMBER)) {
      return {
        type: 'Number',
        value: this.previous().value,
        line: token.line,
        column: token.column,
      };
    }

    // 문자열
    if (this.match(V3TokenType.STRING)) {
      return {
        type: 'String',
        value: this.previous().value,
        line: token.line,
        column: token.column,
      };
    }

    // 불린
    if (this.match(V3TokenType.BOOL)) {
      return {
        type: 'Bool',
        value: this.previous().value,
        line: token.line,
        column: token.column,
      };
    }

    // 배열 리터럴
    if (this.match(V3TokenType.LBRACKET)) {
      const elements: V3Expr[] = [];
      while (!this.check(V3TokenType.RBRACKET)) {
        elements.push(this.parseExpr());
        if (!this.check(V3TokenType.RBRACKET)) {
          this.consume(V3TokenType.COMMA, ', 필요');
        }
      }
      this.consume(V3TokenType.RBRACKET, '] 필요');
      return {
        type: 'ArrayLiteral',
        elements,
        line: token.line,
        column: token.column,
      };
    }

    // 배열 연산 (ARR_SUM 등)
    if (this.checkKeyword('ARR_SUM') || this.checkKeyword('ARR_AVG') || this.checkKeyword('ARR_MAX') || this.checkKeyword('ARR_MIN')) {
      const op = this.advance().value;
      const array = this.parsePostfix();
      return {
        type: 'ArrayOp',
        op,
        array,
        line: token.line,
        column: token.column,
      };
    }

    // 괄호 표현식
    if (this.match(V3TokenType.LPAREN)) {
      const expr = this.parseExpr();
      this.consume(V3TokenType.RPAREN, ') 필요');
      return expr;
    }

    // 식별자
    if (this.match(V3TokenType.IDENTIFIER)) {
      return {
        type: 'Identifier',
        name: this.previous().value,
        line: token.line,
        column: token.column,
      };
    }

    throw new Error(`예상치 못한 토큰: ${token.type} at line ${token.line}`);
  }

  private isType(token: V3Token): boolean {
    if (token.type !== V3TokenType.KEYWORD) return false;
    return ['ARR', 'INT', 'STR', 'BOOL', 'FLOAT'].includes(token.value);
  }

  private checkKeyword(keyword: string): boolean {
    return this.check(V3TokenType.KEYWORD) && this.peekValue() === keyword;
  }

  private match(...args: any[]): boolean {
    for (const arg of args) {
      if (typeof arg === 'string') {
        if (this.check(V3TokenType.KEYWORD) && this.peekValue() === arg) {
          this.advance();
          return true;
        }
      } else if (this.check(arg)) {
        this.advance();
        return true;
      }
    }
    return false;
  }

  private check(type: V3TokenType): boolean {
    if (this.isAtEnd()) return false;
    return this.peek().type === type;
  }

  private advance(): V3Token {
    if (!this.isAtEnd()) this.pos++;
    return this.previous();
  }

  private isAtEnd(): boolean {
    return this.peek().type === V3TokenType.EOF;
  }

  private peek(): V3Token {
    return this.tokens[this.pos];
  }

  private peekValue(): any {
    return this.peek().value;
  }

  private peekAhead(n: number): V3Token | undefined {
    return this.tokens[this.pos + n];
  }

  private previous(): V3Token {
    return this.tokens[this.pos - 1];
  }

  private consume(type: V3TokenType, message: string, value?: string): V3Token {
    if (this.check(type)) {
      if (value && this.peekValue() !== value) {
        throw new Error(`${message} (기대값: ${value}, 실제: ${this.peekValue()})`);
      }
      return this.advance();
    }

    const token = this.peek();
    throw new Error(`${message} at line ${token.line}`);
  }

  private consumeNewline(): void {
    while (this.check(V3TokenType.NEWLINE)) {
      this.advance();
    }
  }
}

