/**
 * V3 Compiler (컴파일러)
 *
 * AST → AIOp 바이트코드 변환
 */

import { V3Program, V3Statement, V3Expr, V3ASTNode } from './v3-parser';
import { AIOp } from './ai-ir';

export class V3Compiler {
  private bytecode: AIOp[] = [];
  private variables: Map<string, number> = new Map();
  private functions: Map<string, { startAddr: number; paramCount: number }> = new Map();
  private loopStack: Array<{ breakAddr: number }> = [];

  compile(program: V3Program): AIOp[] {
    for (const stmt of program.statements) {
      this.compileStatement(stmt);
    }

    // 프로그램 끝
    this.emit(AIOp.RETURN, 0);

    return this.bytecode;
  }

  private compileStatement(stmt: V3Statement): void {
    switch (stmt.type) {
      case 'VarDecl': {
        const varDecl = stmt as any;
        const addr = this.variables.size;
        this.variables.set(varDecl.name, addr);
        this.compileExpr(varDecl.value);
        this.emit(AIOp.STORE, addr);
        break;
      }

      case 'IfStmt': {
        const ifStmt = stmt as any;
        this.compileExpr(ifStmt.condition);
        const jumpIfFalseAddr = this.bytecode.length;
        this.emit(AIOp.JMP_FALSE, 0); // placeholder

        for (const s of ifStmt.thenBlock) {
          this.compileStatement(s);
        }

        const jumpElseAddr = this.bytecode.length;
        this.emit(AIOp.JMP, 0); // placeholder

        // Fix JMP_FALSE
        this.bytecode[jumpIfFalseAddr] = AIOp.JMP_FALSE;
        (this.bytecode as any)[jumpIfFalseAddr + 1] = this.bytecode.length;

        if (ifStmt.elseBlock) {
          for (const s of ifStmt.elseBlock) {
            this.compileStatement(s);
          }
        }

        // Fix JMP
        this.bytecode[jumpElseAddr] = AIOp.JMP;
        (this.bytecode as any)[jumpElseAddr + 1] = this.bytecode.length;
        break;
      }

      case 'ForLoop': {
        const forLoop = stmt as any;
        const loopStartAddr = this.bytecode.length;
        const varAddr = this.variables.size;
        this.variables.set(forLoop.variable, varAddr);

        // iterable 계산
        this.compileExpr(forLoop.iterable);

        // 배열 길이 저장 (간단히 배열 크기 가정)
        const lengthAddr = this.variables.size;
        this.variables.set('__length', lengthAddr);
        this.emit(AIOp.ARR_LEN);
        this.emit(AIOp.STORE, lengthAddr);

        // 인덱스 변수 초기화
        const indexAddr = this.variables.size;
        this.variables.set('__index', indexAddr);
        this.emit(AIOp.PUSH, 0);
        this.emit(AIOp.STORE, indexAddr);

        // 루프 조건 체크
        const loopCondAddr = this.bytecode.length;
        this.emit(AIOp.LOAD, indexAddr);
        this.emit(AIOp.LOAD, lengthAddr);
        this.emit(AIOp.LT);
        const breakAddr = this.bytecode.length;
        this.emit(AIOp.JMP_FALSE, 0); // placeholder

        // 루프 본체
        for (const s of forLoop.body) {
          this.compileStatement(s);
        }

        // 인덱스 증가
        this.emit(AIOp.LOAD, indexAddr);
        this.emit(AIOp.PUSH, 1);
        this.emit(AIOp.ADD);
        this.emit(AIOp.STORE, indexAddr);

        // 루프 재시작
        this.emit(AIOp.JMP, loopCondAddr);

        // Break 주소 수정
        this.bytecode[breakAddr] = AIOp.JMP_FALSE;
        (this.bytecode as any)[breakAddr + 1] = this.bytecode.length;

        break;
      }

      case 'FuncDecl': {
        const funcDecl = stmt as any;
        const startAddr = this.bytecode.length;
        this.functions.set(funcDecl.name, { startAddr, paramCount: funcDecl.params.length });

        // 파라미터 로드 (생략, 간단히 처리)
        for (const s of funcDecl.body) {
          this.compileStatement(s);
        }

        // 함수 끝
        this.emit(AIOp.RETURN, 0);
        break;
      }

      case 'ReturnStmt': {
        const returnStmt = stmt as any;
        if (returnStmt.value) {
          this.compileExpr(returnStmt.value);
        }
        this.emit(AIOp.RETURN, 0);
        break;
      }

      case 'ExprStmt': {
        const exprStmt = stmt as any;
        this.compileExpr(exprStmt.expr);
        break;
      }
    }
  }

  private compileExpr(expr: V3Expr): void {
    switch (expr.type) {
      case 'Number': {
        const numExpr = expr as any;
        this.emit(AIOp.PUSH, numExpr.value);
        break;
      }

      case 'String': {
        const strExpr = expr as any;
        // 문자열은 상수로 PUSH
        this.emit(AIOp.PUSH, strExpr.value);
        break;
      }

      case 'Bool': {
        const boolExpr = expr as any;
        this.emit(AIOp.PUSH, boolExpr.value ? 1 : 0);
        break;
      }

      case 'Identifier': {
        const idExpr = expr as any;
        const addr = this.variables.get(idExpr.name);
        if (addr !== undefined) {
          this.emit(AIOp.LOAD, addr);
        } else {
          throw new Error(`미정의 변수: ${idExpr.name}`);
        }
        break;
      }

      case 'BinaryOp': {
        const binOp = expr as any;
        this.compileExpr(binOp.left);
        this.compileExpr(binOp.right);

        switch (binOp.op) {
          case '+':
            this.emit(AIOp.ADD);
            break;
          case '-':
            this.emit(AIOp.SUB);
            break;
          case '*':
            this.emit(AIOp.MUL);
            break;
          case '/':
            this.emit(AIOp.DIV);
            break;
          case '==':
            this.emit(AIOp.EQ);
            break;
          case '!=':
            this.emit(AIOp.NE);
            break;
          case '<':
            this.emit(AIOp.LT);
            break;
          case '<=':
            this.emit(AIOp.LE);
            break;
          case '>':
            this.emit(AIOp.GT);
            break;
          case '>=':
            this.emit(AIOp.GE);
            break;
          case 'AND':
            this.emit(AIOp.AND);
            break;
          case 'OR':
            this.emit(AIOp.OR);
            break;
        }
        break;
      }

      case 'UnaryOp': {
        const unaryOp = expr as any;
        this.compileExpr(unaryOp.operand);
        if (unaryOp.op === '-') {
          this.emit(AIOp.NEG);
        }
        break;
      }

      case 'ArrayLiteral': {
        const arrLit = expr as any;
        for (const elem of arrLit.elements) {
          this.compileExpr(elem);
        }
        this.emit(AIOp.ARR_NEW, arrLit.elements.length);
        break;
      }

      case 'ArrayAccess': {
        const arrAccess = expr as any;
        this.compileExpr(arrAccess.array);
        this.compileExpr(arrAccess.index);
        this.emit(AIOp.ARRAY_GET);
        break;
      }

      case 'ArrayOp': {
        const arrOp = expr as any;
        this.compileExpr(arrOp.array);

        switch (arrOp.op) {
          case 'ARR_SUM':
            this.emit(AIOp.ARR_SUM);
            break;
          case 'ARR_AVG':
            this.emit(AIOp.ARR_AVG);
            break;
          case 'ARR_MAX':
            this.emit(AIOp.ARR_MAX);
            break;
          case 'ARR_MIN':
            this.emit(AIOp.ARR_MIN);
            break;
        }
        break;
      }

      case 'FuncCall': {
        const funcCall = expr as any;

        // 빌트인 함수
        if (funcCall.name === 'println') {
          for (const arg of funcCall.args) {
            this.compileExpr(arg);
          }
          this.emit(AIOp.CALL_BUILTIN, 1); // println은 인자 1개
        } else if (funcCall.name === 'input') {
          this.emit(AIOp.CALL_BUILTIN, 0);
        } else {
          // 사용자 정의 함수
          const func = this.functions.get(funcCall.name);
          if (func) {
            for (const arg of funcCall.args) {
              this.compileExpr(arg);
            }
            this.emit(AIOp.CALL, func.startAddr);
          } else {
            throw new Error(`미정의 함수: ${funcCall.name}`);
          }
        }
        break;
      }

      case 'Assignment': {
        const assign = expr as any;
        this.compileExpr(assign.value);
        const addr = this.variables.get(assign.name);
        if (addr !== undefined) {
          this.emit(AIOp.STORE, addr);
        } else {
          throw new Error(`미정의 변수: ${assign.name}`);
        }
        break;
      }
    }
  }

  private emit(op: AIOp, arg?: number): void {
    this.bytecode.push(op);
    if (arg !== undefined) {
      this.bytecode.push(arg);
    }
  }
}

