        break;
      }

      case 'ArrayAccess': {
        const arrAccess = expr as any;
        this.compileExpr(arrAccess.array);
        this.compileExpr(arrAccess.index);
        this.emit(AIOp.ARRAY_GET);
        break;
      }

      case 'ArrayOp': {
        const arrOp = expr as any;
        this.compileExpr(arrOp.array);

        switch (arrOp.op) {
          case 'ARR_SUM':
            this.emit(AIOp.ARR_SUM);
            break;
          case 'ARR_AVG':
            this.emit(AIOp.ARR_AVG);
            break;
          case 'ARR_MAX':
            this.emit(AIOp.ARR_MAX);
            break;
          case 'ARR_MIN':
            this.emit(AIOp.ARR_MIN);
            break;
        }
        break;
      }

      case 'FuncCall': {
        const funcCall = expr as any;

        // 빌트인 함수
        if (funcCall.name === 'println') {
          for (const arg of funcCall.args) {
            this.compileExpr(arg);
          }
          this.emit(AIOp.CALL_BUILTIN, 1); // println은 인자 1개
        } else if (funcCall.name === 'input') {
          this.emit(AIOp.CALL_BUILTIN, 0);
        } else {
          // 사용자 정의 함수
          const func = this.functions.get(funcCall.name);
          if (func) {
            for (const arg of funcCall.args) {
              this.compileExpr(arg);
            }
            this.emit(AIOp.CALL, func.startAddr);
          } else {
            throw new Error(`미정의 함수: ${funcCall.name}`);
          }
        }
        break;
      }

      case 'Assignment': {
        const assign = expr as any;
        this.compileExpr(assign.value);
        const addr = this.variables.get(assign.name);
        if (addr !== undefined) {
          this.emit(AIOp.STORE, addr);
        } else {
          throw new Error(`미정의 변수: ${assign.name}`);
        }
        break;
      }
    }
  }

  private emit(op: AIOp, arg?: number): void {
    this.bytecode.push(op);
    if (arg !== undefined) {
      this.bytecode.push(arg);
    }
  }
}

