/**
 * V3 Runtime (런타임)
 *
 * AIVM을 래핑하여 V3 프로그램 실행
 */

import { AIVM } from './ai-vm';

export interface V3RuntimeOptions {
  debug?: boolean;
  maxIterations?: number;
}

export class V3Runtime {
  private vm: AIVM;
  private output: string[] = [];
  private options: V3RuntimeOptions;

  constructor(bytecode: number[], options: V3RuntimeOptions = {}) {
    this.vm = new AIVM(bytecode);
    this.options = {
      debug: false,
      maxIterations: 100000,
      ...options,
    };
  }

  run(): { output: string; success: boolean; error?: string } {
    try {
      this.output = [];

      // AIVM 실행
      let iterations = 0;
      while (!this.vm.isFinished() && iterations < this.options.maxIterations!) {
        this.executeStep();
        iterations++;
      }

      if (iterations >= this.options.maxIterations!) {
        return {
          output: this.output.join('\n'),
          success: false,
          error: '최대 반복 횟수 초과',
        };
      }

      return {
        output: this.output.join('\n'),
        success: true,
      };
    } catch (error) {
      return {
        output: this.output.join('\n'),
        success: false,
        error: (error as any).message,
      };
    }
  }

  private executeStep(): void {
    // AIVM의 단계 실행
    // (실제 구현은 AIVM.step()이 필요)
    // 여기서는 간단한 구현으로 진행
  }

  // 빌트인 함수
  public println(...args: any[]): void {
    this.output.push(args.map(this.stringify).join(' '));
  }

  public input(prompt: string = ''): string {
    // Node.js에서는 실제 입력이 불가능하므로 빈 문자열 반환
    if (prompt) {
      this.output.push(prompt);
    }
    return '';
  }

  private stringify(value: any): string {
    if (Array.isArray(value)) {
      return '[' + value.map(v => this.stringify(v)).join(', ') + ']';
    }
    if (typeof value === 'string') {
      return value;
    }
    if (typeof value === 'boolean') {
      return value ? 'true' : 'false';
    }
    if (value === null) {
      return 'null';
    }
    return String(value);
  }
}

