/**
 * V3 Main Entry Point (CLI)
 *
 * 파일 읽기 → 파싱 → 컴파일 → 실행
 */

import * as fs from 'fs';
import * as path from 'path';
import { V3Parser } from './v3-parser';
import { V3Compiler } from './v3-compiler';
import { V3Runtime } from './v3-runtime';

async function main() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    showHelp();
    process.exit(0);
  }

  const command = args[0];

  if (command === 'help') {
    showHelp();
    process.exit(0);
  }

  if (command === 'run' && args.length >= 2) {
    const filePath = args[1];
    await runFile(filePath);
  } else if (command === 'repl') {
    await startREPL();
  } else {
    console.error(`알 수 없는 명령: ${command}`);
    console.error('사용법: freelang <command> [options]');
    console.error('명령:');
    console.error('  run <file>  - V3 파일 실행');
    console.error('  repl        - 대화형 셸 시작');
    console.error('  help        - 도움말 보기');
    process.exit(1);
  }
}

async function runFile(filePath: string) {
  try {
    // 파일 읽기
    if (!fs.existsSync(filePath)) {
      console.error(`파일을 찾을 수 없음: ${filePath}`);
      process.exit(1);
    }

    const source = fs.readFileSync(filePath, 'utf8');

    // 파싱
    const parser = new V3Parser(source);
    let ast;
    try {
      ast = parser.parse();
    } catch (parseError) {
      console.error(`파싱 오류: ${(parseError as any).message}`);
      process.exit(1);
    }

    // 컴파일
    const compiler = new V3Compiler();
    let bytecode;
    try {
      bytecode = compiler.compile(ast);
    } catch (compileError) {
      console.error(`컴파일 오류: ${(compileError as any).message}`);
      process.exit(1);
    }

    // 실행
    const runtime = new V3Runtime(bytecode as any);
    const result = runtime.run();

    if (result.output) {
      console.log(result.output);
    }

    if (!result.success) {
      console.error(`실행 오류: ${result.error}`);
      process.exit(1);
    }
  } catch (error) {
    console.error(`오류: ${(error as any).message}`);
    process.exit(1);
  }
}

async function startREPL() {
  console.log('V3 대화형 셸 (REPL)');
  console.log('명령: help, exit, clear');
  console.log('');

  const readline = require('readline');
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  const prompt = () => {
    rl.question('v3> ', async (input: string) => {
      const trimmed = input.trim();

      if (trimmed === 'exit') {
        rl.close();
        return;
      }

      if (trimmed === 'help') {
        console.log('V3 대화형 셸 도움말');
        console.log('  help    - 도움말 보기');
        console.log('  exit    - 셸 종료');
        console.log('  clear   - 화면 지우기');
        prompt();
        return;
      }

      if (trimmed === 'clear') {
        console.clear();
        prompt();
        return;
      }

      if (trimmed === '') {
        prompt();
        return;
      }

      try {
        // 단일 표현식 실행
        const parser = new V3Parser(trimmed);
        const ast = parser.parse();
        const compiler = new V3Compiler();
        const bytecode = compiler.compile(ast);
        const runtime = new V3Runtime(bytecode as any);
        const result = runtime.run();

        if (result.output) {
          console.log(result.output);
        }

        if (!result.success) {
          console.error(`오류: ${result.error}`);
        }
      } catch (error) {
        console.error(`오류: ${(error as any).message}`);
      }

      prompt();
    });
  };

  prompt();
}

function showHelp() {
  console.log('FreeLang V3 - 프로그래밍 언어');
  console.log('');
  console.log('사용법:');
  console.log('  freelang run <file>   - V3 파일 실행');
  console.log('  freelang repl         - 대화형 셸');
  console.log('  freelang help         - 도움말');
  console.log('');
  console.log('예제:');
  console.log('  # test.v3 파일 생성');
  console.log('  cat > test.v3 << "EOF"');
  console.log('  ARR nums = [1, 2, 3, 4, 5]');
  console.log('  ARR_SUM nums -> total');
  console.log('  println(total)');
  console.log('  EOF');
  console.log('');
  console.log('  # 실행');
  console.log('  freelang run test.v3');
}

main().catch(error => {
  console.error('오류:', error);
  process.exit(1);
});

