/**
 * V3 Integration Tests
 *
 * Lexer → Parser → Compiler → Runtime 통합 테스트
 */

import { V3Lexer, V3TokenType } from './v3-lexer';
import { V3Parser } from './v3-parser';
import { V3Compiler } from './v3-compiler';
import { V3Runtime } from './v3-runtime';

describe('V3 Integration Tests', () => {
  // 헬퍼 함수: 코드 실행
  function runCode(code: string): { output: string; success: boolean; error?: string } {
    try {
      const parser = new V3Parser(code);
      const ast = parser.parse();
      const compiler = new V3Compiler();
      const bytecode = compiler.compile(ast);
      const runtime = new V3Runtime(bytecode as any);
      return runtime.run();
    } catch (error) {
      return {
        output: '',
        success: false,
        error: (error as any).message,
      };
    }
  }

  describe('Lexer Tests', () => {
    test('should tokenize V3 keywords', () => {
      const lexer = new V3Lexer('INT x = 10');
      const tokens = lexer.tokenize();

      expect(tokens[0].type).toBe(V3TokenType.KEYWORD);
      expect(tokens[0].value).toBe('INT');

      expect(tokens[1].type).toBe(V3TokenType.IDENTIFIER);
      expect(tokens[1].value).toBe('x');

      expect(tokens[2].type).toBe(V3TokenType.ASSIGN);

      expect(tokens[3].type).toBe(V3TokenType.NUMBER);
      expect(tokens[3].value).toBe(10);
    });

    test('should tokenize array literals', () => {
      const lexer = new V3Lexer('ARR nums = [1, 2, 3]');
      const tokens = lexer.tokenize();

      const types = tokens.map(t => t.type);
      expect(types).toContain(V3TokenType.LBRACKET);
      expect(types).toContain(V3TokenType.RBRACKET);
      expect(types).toContain(V3TokenType.COMMA);
    });

    test('should handle string literals', () => {
      const lexer = new V3Lexer('STR msg = "Hello World"');
      const tokens = lexer.tokenize();

      const stringToken = tokens.find(t => t.type === V3TokenType.STRING);
      expect(stringToken).toBeDefined();
      expect(stringToken?.value).toBe('Hello World');
    });

    test('should handle boolean literals', () => {
      const lexer = new V3Lexer('BOOL flag = TRUE');
      const tokens = lexer.tokenize();

      const boolToken = tokens.find(t => t.type === V3TokenType.BOOL);
      expect(boolToken).toBeDefined();
      expect(boolToken?.value).toBe(true);
    });

    test('should handle indentation (INDENT/DEDENT)', () => {
      const code = `IF TRUE:
  println(1)
  println(2)
println(3)`;

      const lexer = new V3Lexer(code);
      const tokens = lexer.tokenize();

      const types = tokens.map(t => t.type);
      expect(types).toContain(V3TokenType.INDENT);
      expect(types).toContain(V3TokenType.DEDENT);
    });
  });

  describe('Parser Tests', () => {
    test('should parse variable declaration', () => {
      const parser = new V3Parser('INT x = 42');
      const ast = parser.parse();

      expect(ast.type).toBe('Program');
      expect(ast.statements.length).toBeGreaterThan(0);
      expect(ast.statements[0].type).toBe('VarDecl');
    });

    test('should parse array declaration', () => {
      const code = 'ARR nums = [1, 2, 3, 4, 5]';
      const parser = new V3Parser(code);
      const ast = parser.parse();

      expect(ast.statements[0].type).toBe('VarDecl');
    });

    test('should parse expressions with operators', () => {
      const parser = new V3Parser('INT result = 10 + 20');
      const ast = parser.parse();

      expect(ast.statements[0].type).toBe('VarDecl');
    });

    test('should parse function calls', () => {
      const code = 'println("Hello")';
      const parser = new V3Parser(code);
      const ast = parser.parse();

      expect(ast.statements[0].type).toBe('ExprStmt');
    });

    test('should parse if statements', () => {
      const code = `IF TRUE:
  println(1)`;
      const parser = new V3Parser(code);
      const ast = parser.parse();

      expect(ast.statements[0].type).toBe('IfStmt');
    });

    test('should parse for loops', () => {
      const code = `FOR n IN [1, 2, 3]:
  println(n)`;
      const parser = new V3Parser(code);
      const ast = parser.parse();

      expect(ast.statements[0].type).toBe('ForLoop');
    });
  });

  describe('Compiler Tests', () => {
    test('should compile simple variable declaration', () => {
      const parser = new V3Parser('INT x = 10');
      const ast = parser.parse();
      const compiler = new V3Compiler();
      const bytecode = compiler.compile(ast);

      expect(Array.isArray(bytecode)).toBe(true);
      expect(bytecode.length).toBeGreaterThan(0);
    });

    test('should compile array operations', () => {
      const code = `ARR nums = [1, 2, 3]
ARR_SUM nums -> total`;
      const parser = new V3Parser(code);
      const ast = parser.parse();
      const compiler = new V3Compiler();
      const bytecode = compiler.compile(ast);

      expect(bytecode.length).toBeGreaterThan(0);
    });

    test('should compile function calls', () => {
      const code = 'println("test")';
      const parser = new V3Parser(code);
      const ast = parser.parse();
      const compiler = new V3Compiler();
      const bytecode = compiler.compile(ast);

      expect(bytecode.length).toBeGreaterThan(0);
    });
  });

  describe('Runtime Tests', () => {
    test('should execute simple variable assignment', () => {
      const result = runCode('INT x = 10\nprintln(x)');
      expect(result.success).toBe(true);
    });

    test('should execute arithmetic operations', () => {
      const result = runCode('INT result = 10 + 20\nprintln(result)');
      expect(result.success).toBe(true);
    });

    test('should handle string concatenation', () => {
      const result = runCode('STR msg = "Hello"\nprintln(msg)');
      expect(result.success).toBe(true);
    });

    test('should evaluate boolean expressions', () => {
      const result = runCode('BOOL flag = TRUE\nprintln(flag)');
      expect(result.success).toBe(true);
    });

    test('should handle array literals', () => {
      const result = runCode('ARR nums = [1, 2, 3]\nprintln(nums)');
      expect(result.success).toBe(true);
    });

