/**
 * V3 Executor (V3 언어 실행 엔진)
 *
 * AST를 직접 해석하여 실행 (Interpreter 방식)
 * - 더 간단하고 명확함
 * - 디버깅 가능
 * - 동작 보장
 */

import { V3Program, V3Statement, V3Expr } from './v3-parser';

export interface V3Value {
  type: 'number' | 'string' | 'boolean' | 'array' | 'function' | 'null';
  value: any;
}

export class V3Executor {
  private globals: Map<string, V3Value> = new Map();
  private locals: Map<string, V3Value>[] = [new Map()];
  private output: string[] = [];
  private returnValue: V3Value | null = null;
  private shouldReturn: boolean = false;
  private functions: Map<string, V3FunctionDef> = new Map();

  interface V3FunctionDef {
    params: Array<{ name: string; type: string }>;
    body: V3Statement[];
  }

  constructor() {
    // 빌트인 함수들
    this.registerBuiltins();
  }

  private registerBuiltins(): void {
    // println은 특수 처리
    // input도 특수 처리
  }

  execute(program: V3Program): { output: string; success: boolean; error?: string } {
    try {
      for (const stmt of program.statements) {
        this.executeStatement(stmt);
        if (this.shouldReturn) break;
      }

      return {
        output: this.output.join('\n'),
        success: true,
      };
    } catch (error) {
      return {
        output: this.output.join('\n'),
        success: false,
        error: (error as any).message,
      };
    }
  }

  private executeStatement(stmt: V3Statement): void {
    switch (stmt.type) {
      case 'VarDecl': {
        const varDecl = stmt as any;
        const value = this.evaluateExpr(varDecl.value);
        this.setVariable(varDecl.name, value);
        break;
      }

      case 'IfStmt': {
        const ifStmt = stmt as any;
        const condition = this.evaluateExpr(ifStmt.condition);
        if (this.isTruthy(condition)) {
          for (const s of ifStmt.thenBlock) {
            this.executeStatement(s);
            if (this.shouldReturn) return;
          }
        } else if (ifStmt.elseBlock) {
          for (const s of ifStmt.elseBlock) {
            this.executeStatement(s);
            if (this.shouldReturn) return;
          }
        }
        break;
      }

      case 'ForLoop': {
        const forLoop = stmt as any;
        const iterable = this.evaluateExpr(forLoop.iterable);

        if (iterable.type !== 'array') {
          throw new Error('FOR IN은 배열에만 사용 가능');
        }

        for (const item of iterable.value) {
          this.setVariable(forLoop.variable, item);
          for (const s of forLoop.body) {
            this.executeStatement(s);
            if (this.shouldReturn) return;
          }
        }
        break;
      }

      case 'FuncDecl': {
        const funcDecl = stmt as any;
        this.functions.set(funcDecl.name, {
          params: funcDecl.params,
          body: funcDecl.body,
        });
        break;
      }

      case 'ReturnStmt': {
        const returnStmt = stmt as any;
        if (returnStmt.value) {
          this.returnValue = this.evaluateExpr(returnStmt.value);
        } else {
          this.returnValue = { type: 'null', value: null };
        }
        this.shouldReturn = true;
        break;
      }

      case 'ExprStmt': {
        const exprStmt = stmt as any;
        this.evaluateExpr(exprStmt.expr);
        break;
      }
    }
  }

  private evaluateExpr(expr: V3Expr): V3Value {
    switch (expr.type) {
      case 'Number': {
        const numExpr = expr as any;
        return { type: 'number', value: numExpr.value };
      }

      case 'String': {
        const strExpr = expr as any;
        return { type: 'string', value: strExpr.value };
      }

      case 'Bool': {
        const boolExpr = expr as any;
        return { type: 'boolean', value: boolExpr.value };
      }

      case 'Identifier': {
        const idExpr = expr as any;
        return this.getVariable(idExpr.name);
      }

      case 'ArrayLiteral': {
        const arrLit = expr as any;
        const elements = arrLit.elements.map((e: V3Expr) => this.evaluateExpr(e));
        return { type: 'array', value: elements };
      }

      case 'BinaryOp': {
        const binOp = expr as any;
        const left = this.evaluateExpr(binOp.left);
        const right = this.evaluateExpr(binOp.right);

        switch (binOp.op) {
          case '+':
            if (left.type === 'number' && right.type === 'number') {
              return { type: 'number', value: left.value + right.value };
            }
            if (left.type === 'string' || right.type === 'string') {
              return { type: 'string', value: String(left.value) + String(right.value) };
            }
            throw new Error(`+ 연산 불가: ${left.type} + ${right.type}`);

          case '-':
            if (left.type === 'number' && right.type === 'number') {
              return { type: 'number', value: left.value - right.value };
            }
            throw new Error(`- 연산 불가: ${left.type} - ${right.type}`);

          case '*':
            if (left.type === 'number' && right.type === 'number') {
              return { type: 'number', value: left.value * right.value };
            }
            throw new Error(`* 연산 불가: ${left.type} * ${right.type}`);

          case '/':
            if (left.type === 'number' && right.type === 'number') {
              if (right.value === 0) throw new Error('0으로 나눌 수 없음');
              return { type: 'number', value: left.value / right.value };
            }
            throw new Error(`/ 연산 불가: ${left.type} / ${right.type}`);

          case '==':
            return { type: 'boolean', value: this.areEqual(left, right) };

          case '!=':
            return { type: 'boolean', value: !this.areEqual(left, right) };

          case '<':
            if (left.type === 'number' && right.type === 'number') {
              return { type: 'boolean', value: left.value < right.value };
            }
            throw new Error(`< 연산 불가: ${left.type} < ${right.type}`);

          case '<=':
            if (left.type === 'number' && right.type === 'number') {
              return { type: 'boolean', value: left.value <= right.value };
            }
            throw new Error(`<= 연산 불가: ${left.type} <= ${right.type}`);

          case '>':
            if (left.type === 'number' && right.type === 'number') {
              return { type: 'boolean', value: left.value > right.value };
            }
            throw new Error(`> 연산 불가: ${left.type} > ${right.type}`);

          case '>=':
            if (left.type === 'number' && right.type === 'number') {
              return { type: 'boolean', value: left.value >= right.value };
            }
            throw new Error(`>= 연산 불가: ${left.type} >= ${right.type}`);

          case 'AND':
            return { type: 'boolean', value: this.isTruthy(left) && this.isTruthy(right) };

          case 'OR':
            return { type: 'boolean', value: this.isTruthy(left) || this.isTruthy(right) };

          default:
            throw new Error(`미지원 연산: ${binOp.op}`);
        }
      }

      case 'UnaryOp': {
        const unaryOp = expr as any;
        const operand = this.evaluateExpr(unaryOp.operand);

        if (unaryOp.op === '-') {
          if (operand.type === 'number') {
            return { type: 'number', value: -operand.value };
          }
          throw new Error(`- 단항 연산 불가: ${operand.type}`);
        }

        throw new Error(`미지원 단항 연산: ${unaryOp.op}`);
      }

      case 'ArrayAccess': {
        const arrAccess = expr as any;
        const array = this.evaluateExpr(arrAccess.array);
        const index = this.evaluateExpr(arrAccess.index);

        if (array.type !== 'array') {
          throw new Error('배열이 아님');
        }
        if (index.type !== 'number') {
          throw new Error('인덱스는 숫자여야 함');
        }

        const idx = Math.floor(index.value);
        if (idx < 0 || idx >= array.value.length) {
          throw new Error(`인덱스 범위 초과: ${idx}`);
        }

        return array.value[idx];
      }

      case 'ArrayOp': {
        const arrOp = expr as any;
        const array = this.evaluateExpr(arrOp.array);

        if (array.type !== 'array') {
          throw new Error('배열이 아님');
        }

        const nums = array.value.map((v: V3Value) => {
          if (v.type !== 'number') throw new Error('배열 원소는 숫자여야 함');
          return v.value;
        });

        switch (arrOp.op) {
          case 'ARR_SUM':
            return { type: 'number', value: nums.reduce((a: number, b: number) => a + b, 0) };

          case 'ARR_AVG':
            return {
              type: 'number',
              value: nums.length > 0 ? nums.reduce((a: number, b: number) => a + b, 0) / nums.length : 0,
            };

          case 'ARR_MAX':
            return { type: 'number', value: nums.length > 0 ? Math.max(...nums) : 0 };

          case 'ARR_MIN':
            return { type: 'number', value: nums.length > 0 ? Math.min(...nums) : 0 };

          default:
            throw new Error(`미지원 배열 연산: ${arrOp.op}`);
        }
      }

      case 'FuncCall': {
        const funcCall = expr as any;

        // 빌트인 함수
        if (funcCall.name === 'println') {
          const args = funcCall.args.map((arg: V3Expr) => this.evaluateExpr(arg));
          this.output.push(args.map((v: V3Value) => this.stringify(v)).join(' '));
          return { type: 'null', value: null };
        }

        if (funcCall.name === 'input') {
          // Node.js에서는 동기 입력 불가능, 빈 문자열 반환
          return { type: 'string', value: '' };
        }

        // 사용자 정의 함수
        const func = this.functions.get(funcCall.name);
        if (!func) {
          throw new Error(`미정의 함수: ${funcCall.name}`);
        }

        // 새 스코프 생성
        this.locals.push(new Map());

        // 파라미터 바인딩
        const args = funcCall.args.map((arg: V3Expr) => this.evaluateExpr(arg));
        for (let i = 0; i < func.params.length; i++) {
          const param = func.params[i];
          const arg = args[i] || { type: 'null', value: null };
          this.setVariable(param.name, arg);
        }

        // 함수 본체 실행
        this.returnValue = null;
        this.shouldReturn = false;
        for (const stmt of func.body) {
          this.executeStatement(stmt);
          if (this.shouldReturn) break;
        }

        const result = this.returnValue || { type: 'null', value: null };
        this.returnValue = null;
        this.shouldReturn = false;

        // 스코프 복원
        this.locals.pop();

        return result;
      }

      case 'Assignment': {
        const assign = expr as any;
        const value = this.evaluateExpr(assign.value);
        this.setVariable(assign.name, value);
        return value;
      }

      default:
        throw new Error(`미지원 표현식: ${(expr as any).type}`);
    }
  }

  private isTruthy(value: V3Value): boolean {
    switch (value.type) {
      case 'null':
        return false;
      case 'boolean':
        return value.value;
      case 'number':
        return value.value !== 0;
      case 'string':
        return value.value.length > 0;
      case 'array':
        return value.value.length > 0;
      default:
        return true;
    }
  }

  private areEqual(a: V3Value, b: V3Value): boolean {
    if (a.type !== b.type) return false;
    return a.value === b.value;
  }

  private stringify(value: V3Value): string {
    switch (value.type) {
      case 'null':
        return 'null';
      case 'boolean':
        return value.value ? 'true' : 'false';
      case 'number':
        return String(value.value);
      case 'string':
        return value.value;
      case 'array':
        return '[' + value.value.map((v: V3Value) => this.stringify(v)).join(', ') + ']';
      case 'function':
        return '<function>';
      default:
        return String(value);
    }
  }

  private getVariable(name: string): V3Value {
    // 지역 스코프에서 먼저 찾기
    for (let i = this.locals.length - 1; i >= 0; i--) {
      if (this.locals[i].has(name)) {
        return this.locals[i].get(name)!;
      }
    }

    // 전역 스코프에서 찾기
    if (this.globals.has(name)) {
      return this.globals.get(name)!;
    }

    throw new Error(`미정의 변수: ${name}`);
  }

  private setVariable(name: string, value: V3Value): void {
    // 이미 존재하면 업데이트
    for (let i = this.locals.length - 1; i >= 0; i--) {
      if (this.locals[i].has(name)) {
        this.locals[i].set(name, value);
        return;
      }
    }

    if (this.globals.has(name)) {
      this.globals.set(name, value);
      return;
    }

    // 새로 선언
    const scope = this.locals[this.locals.length - 1];
    scope.set(name, value);
  }
}

