/**
 * V3 Complete - 전체 통합 (Lexer → Parser → Executor)
 *
 * 완전히 동작하는 V3 언어 구현
 */

import * as fs from 'fs';
import { V3Lexer } from './v3-lexer';
import { V3Parser } from './v3-parser';
import { V3Executor } from './v3-executor';

export async function runV3Code(source: string): Promise<{ output: string; success: boolean; error?: string }> {
  try {
    // 1. Lexer: 코드 → 토큰
    const lexer = new V3Lexer(source);
    const tokens = lexer.tokenize();

    if (tokens.length === 0) {
      return { output: '', success: true };
    }

    // 2. Parser: 토큰 → AST
    const parser = new V3Parser(source);
    const ast = parser.parse();

    // 3. Executor: AST → 실행
    const executor = new V3Executor();
    const result = executor.execute(ast);

    return result;
  } catch (error) {
    return {
      output: '',
      success: false,
      error: (error as any).message,
    };
  }
}

export async function runV3File(filePath: string): Promise<{ output: string; success: boolean; error?: string }> {
  try {
    if (!fs.existsSync(filePath)) {
      return {
        output: '',
        success: false,
        error: `파일을 찾을 수 없음: ${filePath}`,
      };
    }

    const source = fs.readFileSync(filePath, 'utf8');
    return runV3Code(source);
  } catch (error) {
    return {
      output: '',
      success: false,
      error: (error as any).message,
    };
  }
}

// CLI 실행
async function main() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    showHelp();
    process.exit(0);
  }

  const command = args[0];

  if (command === 'run' && args.length >= 2) {
    const filePath = args[1];
    const result = await runV3File(filePath);

    if (result.output) {
      console.log(result.output);
    }

    if (!result.success) {
      console.error(`오류: ${result.error}`);
      process.exit(1);
    }
  } else if (command === 'repl') {
    await startREPL();
  } else if (command === 'help') {
    showHelp();
  } else {
    console.error(`알 수 없는 명령: ${command}`);
    process.exit(1);
  }
}

async function startREPL() {
  console.log('V3 Interactive Shell');
  console.log('명령: help, exit, clear');
  console.log('');

  const readline = require('readline');
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  const prompt = () => {
    rl.question('v3> ', async (input: string) => {
      const trimmed = input.trim();

      if (trimmed === 'exit') {
        rl.close();
        return;
      }

      if (trimmed === 'help') {
        console.log('V3 Help:');
        console.log('  help    - 도움말');
        console.log('  exit    - 종료');
        console.log('  clear   - 화면 지우기');
        prompt();
        return;
      }

      if (trimmed === 'clear') {
        console.clear();
        prompt();
        return;
      }

      if (trimmed === '') {
        prompt();
        return;
      }

      const result = await runV3Code(trimmed);

      if (result.output) {
        console.log(result.output);
      }

      if (!result.success) {
        console.error(`오류: ${result.error}`);
      }

      prompt();
    });
  };

  prompt();
}

function showHelp() {
  console.log('FreeLang V3 - Programming Language');
  console.log('');
  console.log('Usage:');
  console.log('  v3 run <file>   - Run V3 file');
  console.log('  v3 repl         - Interactive shell');
  console.log('  v3 help         - Show help');
  console.log('');
  console.log('Example:');
  console.log('  cat > test.v3 << EOF');
  console.log('  INT x = 10');
  console.log('  ARR nums = [1, 2, 3, 4, 5]');
  console.log('  ARR_SUM nums -> total');
  console.log('  println(total)');
  console.log('  EOF');
  console.log('');
  console.log('  v3 run test.v3');
}

// 직접 실행될 경우
if (require.main === module) {
  main().catch(error => {
    console.error('오류:', error);
    process.exit(1);
  });
}

export { V3Lexer, V3Parser, V3Executor };

