        value += this.peek();
        this.pos++;
        this.column++;
      }
    }

    this.addToken('NUMBER', parseFloat(value));
  }

  consumeIdentifierOrKeyword() {
    let value = '';
    while (
      this.pos < this.source.length &&
      (this.isLetter(this.peek()) || this.isDigit(this.peek()) || this.peek() === '_')
    ) {
      value += this.peek();
      this.pos++;
      this.column++;
    }

    const KEYWORDS = new Set([
      'ARR', 'INT', 'STR', 'BOOL', 'FLOAT',
      'ARR_SUM', 'ARR_AVG', 'ARR_MAX', 'ARR_MIN',
      'IF', 'ELSE', 'FOR', 'IN', 'WHILE',
      'FUNC', 'RETURN', 'CALL',
      'TRUE', 'FALSE', 'NONE', 'PRINTLN',
    ]);

    if (KEYWORDS.has(value)) {
      if (value === 'TRUE') {
        this.addToken('BOOL', true);
      } else if (value === 'FALSE') {
        this.addToken('BOOL', false);
      } else {
        this.addToken('KEYWORD', value);
      }
    } else {
      this.addToken('IDENTIFIER', value);
    }
  }

  consumeOperatorOrSymbol() {
    const ch = this.peek();
    const next = this.peekNext();

    if (ch === '-' && next === '>') {
      this.pos += 2;
      this.column += 2;
      this.addToken('ARROW', '->');
      return true;
    }

    if (ch === '=' && next === '=') {
      this.pos += 2;
      this.column += 2;
      this.addToken('EQ', '==');
      return true;
    }

    if (ch === '!' && next === '=') {
      this.pos += 2;
      this.column += 2;
      this.addToken('NE', '!=');
      return true;
    }

    if (ch === '<' && next === '=') {
      this.pos += 2;
      this.column += 2;
      this.addToken('LE', '<=');
      return true;
    }

    if (ch === '>' && next === '=') {
      this.pos += 2;
      this.column += 2;
      this.addToken('GE', '>=');
      return true;
    }

    const singleCharTokens = {
