      '-': 'MINUS',
      '*': 'STAR',
      '/': 'SLASH',
      '=': 'ASSIGN',
      '<': 'LT',
      '>': 'GT',
      '(': 'LPAREN',
      ')': 'RPAREN',
      '[': 'LBRACKET',
      ']': 'RBRACKET',
      ':': 'COLON',
      ',': 'COMMA',
      '.': 'DOT',
    };

