// 간단한 Executor (파싱 없이 직접 실행)
function runV3Simple(source) {
  const output = [];

  // 간단한 상태 머신
  const lines = source.split('\n');
  const variables = {};

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    // INT x = 10
    const intMatch = trimmed.match(/^INT\s+(\w+)\s*=\s*(.+)$/);
    if (intMatch) {
      const [, name, expr] = intMatch;
      variables[name] = eval(expr.replace(/\w+/g, (match) => variables[match] ?? match));
      continue;
    }

    // STR x = "value"
    const strMatch = trimmed.match(/^STR\s+(\w+)\s*=\s*"(.*)"/);
    if (strMatch) {
      const [, name, value] = strMatch;
      variables[name] = value;
      continue;
    }

    // ARR x = [...]
    const arrMatch = trimmed.match(/^ARR\s+(\w+)\s*=\s*\[(.*)\]$/);
    if (arrMatch) {
      const [, name, elements] = arrMatch;
      variables[name] = elements.split(',').map((e) => {
        const num = parseInt(e.trim());
        return isNaN(num) ? e.trim() : num;
      });
      continue;
    }

    // ARR_SUM arr -> var
    const sumMatch = trimmed.match(/^ARR_SUM\s+(\w+)\s*->\s*(\w+)$/);
    if (sumMatch) {
      const [, arrName, varName] = sumMatch;
      const arr = variables[arrName];
      if (Array.isArray(arr)) {
        variables[varName] = arr.reduce((a, b) => a + b, 0);
      }
      continue;
    }

    // println(...)
    if (trimmed.startsWith('println(')) {
      const match = trimmed.match(/println\((.*)\)$/);
      if (match) {
        const expr = match[1];
        let value = expr;

        // 변수 대체
        for (const [name, val] of Object.entries(variables)) {
          const regex = new RegExp(`\\b${name}\\b`, 'g');
          if (typeof val === 'string') {
            value = value.replace(regex, `"${val}"`);
          } else if (Array.isArray(val)) {
            value = value.replace(regex, JSON.stringify(val));
          } else {
            value = value.replace(regex, val);
          }
        }

        try {
          const result = eval(value);
          output.push(String(result));
        } catch (e) {
          output.push(value);
        }
      }
      continue;
    }
  }

  return output.join('\n');
}

