function test(filename, expected) {
  console.log(`\n테스트: ${filename}`);
  console.log('---');

  if (!fs.existsSync(filename)) {
    console.error(`❌ 파일 없음: ${filename}`);
    return;
  }

  const code = fs.readFileSync(filename, 'utf8');
