/**
 * V3 Bytecode Generator - AST → Bytecode 변환 (V3-Compiler 개선 버전)
 *
 * 더 체계적인 바이트코드 생성
 * - 스택 기반 명령어
 * - 변수 주소 할당
 * - 제어흐름 라벨링
 */

import { V3Program, V3Statement, V3Expr } from './v3-parser';
import { V3BytecodeInstruction } from './v3-jit';

export interface V3BytecodeContext {
  instructions: V3BytecodeInstruction[];
  variables: Map<string, number>;
  functions: Map<string, number>;
  labels: Map<string, number>;
  nextVarAddr: number;
  nextLabel: number;
}

export class V3BytecodeGenerator {
  private context: V3BytecodeContext;

  constructor() {
    this.context = {
      instructions: [],
      variables: new Map(),
      functions: new Map(),
      labels: new Map(),
      nextVarAddr: 0,
      nextLabel: 0,
    };
  }

  /**
   * AST → Bytecode 변환
   */
  generate(program: V3Program): V3BytecodeInstruction[] {
    for (const stmt of program.statements) {
      this.generateStatement(stmt);
    }

    // 프로그램 끝
    this.emit('HALT');

    return this.context.instructions;
  }

  private generateStatement(stmt: V3Statement): void {
    switch (stmt.type) {
      case 'VarDecl': {
        const varDecl = stmt as any;
        const addr = this.allocateVar(varDecl.name);
        this.generateExpr(varDecl.value);
        this.emit('STORE', addr);
        break;
      }

      case 'IfStmt': {
        const ifStmt = stmt as any;
        this.generateExpr(ifStmt.condition);

        const falseLabel = this.createLabel();
        const endLabel = this.createLabel();

        this.emit('JMP_NOT', falseLabel);

        // Then block
        for (const s of ifStmt.thenBlock) {
          this.generateStatement(s);
        }

        this.emit('JMP', endLabel);

        // False label
        this.resolveLabel(falseLabel);

        // Else block
        if (ifStmt.elseBlock) {
          for (const s of ifStmt.elseBlock) {
            this.generateStatement(s);
          }
        }

        // End label
        this.resolveLabel(endLabel);
        break;
      }

      case 'ForLoop': {
        const forLoop = stmt as any;
        const varAddr = this.allocateVar(forLoop.variable);
        const idxAddr = this.allocateVar(`__idx_${forLoop.variable}`);
        const arrAddr = this.allocateVar(`__arr_${forLoop.variable}`);

        // 배열 생성
        this.generateExpr(forLoop.iterable);
        this.emit('STORE', arrAddr);

        // 인덱스 초기화
        this.emit('PUSH', 0);
        this.emit('STORE', idxAddr);

        // 루프 시작
        const loopStart = this.context.instructions.length;
        const loopEnd = this.createLabel();

        // 배열 길이 확인
        this.emit('LOAD', arrAddr);
        this.emit('ARR_LEN');
        this.emit('LOAD', idxAddr);
        this.emit('GT');
        this.emit('JMP_NOT', loopEnd);

        // 변수에 현재 값 할당
        this.emit('LOAD', arrAddr);
        this.emit('LOAD', idxAddr);
        this.emit('ARR_GET');
        this.emit('STORE', varAddr);

        // 루프 본체
        for (const s of forLoop.body) {
          this.generateStatement(s);
        }

        // 인덱스 증가
        this.emit('LOAD', idxAddr);
        this.emit('PUSH', 1);
        this.emit('ADD');
        this.emit('STORE', idxAddr);

        // 루프 재시작
        this.emit('JMP', loopStart);

        // 루프 끝
        this.resolveLabel(loopEnd);
        break;
      }

      case 'FuncDecl': {
        const funcDecl = stmt as any;
        const funcAddr = this.context.instructions.length;
        this.context.functions.set(funcDecl.name, funcAddr);

        // 함수 본체
        for (const s of funcDecl.body) {
          this.generateStatement(s);
        }

        // 기본 반환값
        if (!this.lastIsReturn()) {
          this.emit('PUSH', null);
          this.emit('RET');
        }
        break;
      }

      case 'ReturnStmt': {
        const returnStmt = stmt as any;
        if (returnStmt.value) {
          this.generateExpr(returnStmt.value);
        } else {
          this.emit('PUSH', null);
        }
        this.emit('RET');
        break;
      }

      case 'ExprStmt': {
        const exprStmt = stmt as any;
        this.generateExpr(exprStmt.expr);
        break;
      }
    }
  }

  private generateExpr(expr: V3Expr): void {
    switch (expr.type) {
      case 'Number': {
        const numExpr = expr as any;
        this.emit('PUSH', numExpr.value);
        break;
      }

      case 'String': {
        const strExpr = expr as any;
        this.emit('PUSH', strExpr.value);
        break;
      }

      case 'Bool': {
        const boolExpr = expr as any;
        this.emit('PUSH', boolExpr.value ? 1 : 0);
        break;
      }

      case 'Identifier': {
        const idExpr = expr as any;
        const addr = this.context.variables.get(idExpr.name);
        if (addr !== undefined) {
          this.emit('LOAD', addr);
        } else {
          // 상수로 간주
          this.emit('PUSH', idExpr.name);
        }
        break;
      }

      case 'BinaryOp': {
        const binOp = expr as any;
        this.generateExpr(binOp.left);
        this.generateExpr(binOp.right);

        switch (binOp.op) {
          case '+':
            this.emit('ADD');
            break;
          case '-':
            this.emit('SUB');
            break;
          case '*':
            this.emit('MUL');
            break;
          case '/':
            this.emit('DIV');
            break;
          case '==':
            this.emit('EQ');
            break;
          case '!=':
            this.emit('NEQ');
            break;
          case '<':
            this.emit('LT');
            break;
          case '<=':
            this.emit('LTE');
            break;
          case '>':
            this.emit('GT');
            break;
          case '>=':
            this.emit('GTE');
            break;
          case 'AND':
            this.emit('AND');
            break;
          case 'OR':
            this.emit('OR');
            break;
        }
        break;
      }

      case 'UnaryOp': {
        const unaryOp = expr as any;
        this.generateExpr(unaryOp.operand);
        if (unaryOp.op === '-') {
          this.emit('NEG');
        }
        break;
      }

      case 'ArrayLiteral': {
        const arrLit = expr as any;
        for (const elem of arrLit.elements) {
          this.generateExpr(elem);
        }
        this.emit('ARR_NEW', arrLit.elements.length);
        break;
      }

      case 'ArrayAccess': {
        const arrAccess = expr as any;
        this.generateExpr(arrAccess.array);
        this.generateExpr(arrAccess.index);
        this.emit('ARR_GET');
        break;
      }

      case 'ArrayOp': {
        const arrOp = expr as any;
        this.generateExpr(arrOp.array);

        switch (arrOp.op) {
          case 'ARR_SUM':
            this.emit('ARR_SUM');
            break;
          case 'ARR_AVG':
            this.emit('ARR_AVG');
            break;
          case 'ARR_MAX':
            this.emit('ARR_MAX');
            break;
          case 'ARR_MIN':
            this.emit('ARR_MIN');
            break;
        }
        break;
      }

      case 'FuncCall': {
        const funcCall = expr as any;

        // 빌트인 함수
        if (funcCall.name === 'println') {
          for (const arg of funcCall.args) {
            this.generateExpr(arg);
          }
          // println은 특수 처리 필요
          this.emit('CALL', -1); // -1 = println
        } else {
          // 사용자 정의 함수
          const funcAddr = this.context.functions.get(funcCall.name);
          if (funcAddr !== undefined) {
            for (const arg of funcCall.args) {
              this.generateExpr(arg);
            }
            this.emit('CALL', funcAddr);
          }
        }
        break;
      }

      case 'Assignment': {
        const assign = expr as any;
        this.generateExpr(assign.value);
        const addr = this.context.variables.get(assign.name);
        if (addr !== undefined) {
          this.emit('STORE', addr);
        }
        break;
      }
    }
  }

  private emit(op: string, arg?: any): void {
    const instruction: V3BytecodeInstruction = { op, arg };
    this.context.instructions.push(instruction);
  }

  private allocateVar(name: string): number {
    if (this.context.variables.has(name)) {
      return this.context.variables.get(name)!;
    }

    const addr = this.context.nextVarAddr++;
    this.context.variables.set(name, addr);
    return addr;
  }

  private createLabel(): string {
    return `L${this.context.nextLabel++}`;
  }

  private resolveLabel(label: string): void {
    this.context.labels.set(label, this.context.instructions.length);
  }

  private lastIsReturn(): boolean {
    const last = this.context.instructions[this.context.instructions.length - 1];
    return last && last.op === 'RET';
  }
}

/**
 * V3 프로그램 → Bytecode 변환
 */
export function programToBytecode(program: V3Program): V3BytecodeInstruction[] {
  const gen = new V3BytecodeGenerator();
  return gen.generate(program);
}

