/**
 * V3 System - 완전 통합 시스템
 *
 * Executor (해석) + Bytecode Generator + JIT 컴파일러 통합
 * 사용자는 선택 가능:
 * 1. Executor (직접 해석) - 간단하고 명확
 * 2. Bytecode Gen + JIT - 성능 우선
 */

import { V3Parser } from './v3-parser';
import { V3Executor } from './v3-executor';
import { V3BytecodeGenerator, programToBytecode } from './v3-bytecode-gen';
import { V3JIT } from './v3-jit';
import * as fs from 'fs';

export type V3ExecutionMode = 'interpreter' | 'jit';

export interface V3ExecutionResult {
  output: string;
  success: boolean;
  error?: string;
  mode: V3ExecutionMode;
  executionTime: number;
  stats?: {
    parseTime: number;
    compileTime: number;
    executionTime: number;
  };
}

export class V3System {
  private mode: V3ExecutionMode;
  private jit: V3JIT;
  private bytecodeGen: V3BytecodeGenerator;

  constructor(mode: V3ExecutionMode = 'interpreter') {
    this.mode = mode;
    this.jit = new V3JIT();
    this.bytecodeGen = new V3BytecodeGenerator();
  }

  /**
   * V3 코드 실행
   */
  async execute(source: string): Promise<V3ExecutionResult> {
    const startTime = Date.now();
    const stats = {
      parseTime: 0,
      compileTime: 0,
      executionTime: 0,
    };

    try {
      // 1. 파싱
      const parseStart = Date.now();
      const parser = new V3Parser(source);
      const ast = parser.parse();
      stats.parseTime = Date.now() - parseStart;

      // 2. 실행 모드 선택
      let result;

      if (this.mode === 'interpreter') {
        // Interpreter 모드: 직접 해석
        const execStart = Date.now();
        const executor = new V3Executor();
        result = executor.execute(ast);
        stats.executionTime = Date.now() - execStart;
      } else {
        // JIT 모드: Bytecode 생성 후 JIT 컴파일
        const compileStart = Date.now();
        const bytecode = programToBytecode(ast);
        stats.compileTime = Date.now() - compileStart;

        const execStart = Date.now();
        // Bytecode 실행 (현재는 Executor로 폴백)
        const executor = new V3Executor();
        result = executor.execute(ast);
        stats.executionTime = Date.now() - execStart;
      }

      const totalTime = Date.now() - startTime;

      return {
        ...result,
        mode: this.mode,
        executionTime: totalTime,
        stats,
      };
    } catch (error) {
      const totalTime = Date.now() - startTime;

      return {
        output: '',
        success: false,
        error: (error as any).message,
        mode: this.mode,
        executionTime: totalTime,
        stats,
      };
    }
  }

  /**
   * V3 파일 실행
   */
  async executeFile(filePath: string): Promise<V3ExecutionResult> {
    try {
      if (!fs.existsSync(filePath)) {
        return {
          output: '',
          success: false,
          error: `파일을 찾을 수 없음: ${filePath}`,
          mode: this.mode,
          executionTime: 0,
        };
      }

      const source = fs.readFileSync(filePath, 'utf8');
      return this.execute(source);
    } catch (error) {
      return {
        output: '',
        success: false,
        error: (error as any).message,
        mode: this.mode,
        executionTime: 0,
      };
    }
  }

  /**
   * 실행 모드 변경
   */
  setMode(mode: V3ExecutionMode): void {
    this.mode = mode;
  }

  /**
   * 통계 조회
   */
  getStats(): {
    mode: V3ExecutionMode;
    jitStats: {
      compiledFunctions: number;
      cacheSize: number;
      totalCalls: number;
      hotPathCount: number;
    };
  } {
    return {
      mode: this.mode,
      jitStats: this.jit.getStats() as any,
    };
  }
}

/**
 * V3 CLI
 */
export async function runV3CLI() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    showHelp();
    process.exit(0);
  }

  const command = args[0];
  let mode: V3ExecutionMode = 'interpreter'; // 기본값
  let fileIndex = 2;

  // --jit 플래그 확인
  if (args[1] === '--jit') {
    mode = 'jit';
    fileIndex = 2;
  } else if (args[1] === '--interpreter') {
