    }

    // 통계 출력
    if (process.argv.includes('--stats')) {
      console.log('\n📊 실행 통계:');
      console.log(`모드: ${result.mode}`);
      console.log(`파싱: ${result.stats?.parseTime}ms`);
      console.log(`컴파일: ${result.stats?.compileTime}ms`);
      console.log(`실행: ${result.stats?.executionTime}ms`);
      console.log(`총 시간: ${result.executionTime}ms`);
    }
  } else if (command === 'repl') {
    await startREPL(mode);
  } else if (command === 'bench') {
    await runBenchmark();
  } else if (command === 'help') {
    showHelp();
  } else {
