            stack.push(Math.max(...arr));
            break;
          }
          case 'ARR_MIN': {
            const arr = stack.pop();
            stack.push(Math.min(...arr));
            break;
          }

          // Built-in functions
          case 'CALL':
            if (instr.arg === -1) {
              // println
              const arg = stack.pop();
              this.output.push(this.stringify(arg));
            }
            break;

          case 'HALT':
            pc = bytecode.length; // 종료
            break;

          case 'RET':
            pc = bytecode.length; // 종료
            break;

          // 제어흐름은 간단히 처리
          case 'JMP':
          case 'JMP_IF':
          case 'JMP_NOT':
            // Skip - 인터프리터에서 처리
            break;
        }

        pc++;
      }

      const result = stack.length > 0 ? stack[stack.length - 1] : undefined;

      return {
        success: true,
        value: result,
        output: this.output.join('\n'),
        executionTime: Date.now() - startTime,
      };
    } catch (error) {
      return {
        success: false,
        output: this.output.join('\n'),
        error: (error as any).message,
        executionTime: Date.now() - startTime,
      };
    }
  }

  private stringify(value: any): string {
    if (Array.isArray(value)) {
      return '[' + value.map((v) => this.stringify(v)).join(', ') + ']';
    }
    if (typeof value === 'string') {
      return value;
    }
    if (typeof value === 'boolean') {
      return value ? 'true' : 'false';
    }
    if (value === null || value === undefined) {
      return 'null';
    }
    return String(value);
  }
}

/**
 * 완전 파이프라인: Lexer → Parser → BytecodeGen → Runtime
 */
export async function executeV3Full(source: string): Promise<V3RuntimeResult> {
  try {
    const { V3Parser } = require('./v3-parser');
