      if (ch === '"') {
        this.consumeString();
        continue;
      }

      if (this.isDigit(ch)) {
        this.consumeNumber();
        continue;
      }

      if (this.isLetter(ch) || ch === '_') {
        this.consumeIdentifier();
        continue;
      }

      this.consumeOperator();
    }

    this.tokens.push({ type: 'EOF', value: null });
    return this.tokens;
  }

  skipWhitespace() {
    while (this.pos < this.source.length && this.peek() === ' ') {
      this.pos++;
      this.column++;
    }
  }

  isNewline() {
    return this.peek() === '\n';
  }

  isComment() {
    return this.peek() === '#';
  }

  isDigit(ch) {
    return ch >= '0' && ch <= '9';
  }

  isLetter(ch) {
    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
  }

  peek() {
    return this.pos < this.source.length ? this.source[this.pos] : '\0';
  }

  peekNext() {
    return this.pos + 1 < this.source.length ? this.source[this.pos + 1] : '\0';
  }

  consumeString() {
    this.pos++; // skip "
    let value = '';
    while (this.peek() !== '"' && this.pos < this.source.length) {
      value += this.peek();
      this.pos++;
    }
    this.pos++; // skip closing "
    this.tokens.push({ type: 'STRING', value });
  }

  consumeNumber() {
    let value = '';
    while (this.isDigit(this.peek())) {
      value += this.peek();
      this.pos++;
    }
    this.tokens.push({ type: 'NUMBER', value: parseInt(value) });
  }

  consumeIdentifier() {
    let value = '';
    while (this.isLetter(this.peek()) || this.isDigit(this.peek()) || this.peek() === '_') {
      value += this.peek();
      this.pos++;
    }

