    if (keywords.includes(value)) {
      this.tokens.push({ type: 'KEYWORD', value });
    } else {
      this.tokens.push({ type: 'IDENTIFIER', value });
    }
  }

  consumeOperator() {
    const ch = this.peek();
    const next = this.peekNext();

    if (ch === '=' && next === '=') {
      this.tokens.push({ type: 'OP', value: '==' });
      this.pos += 2;
    } else if (ch === '!' && next === '=') {
      this.tokens.push({ type: 'OP', value: '!=' });
      this.pos += 2;
    } else if (ch === '-' && next === '>') {
      this.tokens.push({ type: 'ARROW', value: '->' });
      this.pos += 2;
    } else if (ch === '<' && next === '=') {
      this.tokens.push({ type: 'OP', value: '<=' });
      this.pos += 2;
    } else if (ch === '>' && next === '=') {
      this.tokens.push({ type: 'OP', value: '>=' });
