        bytecode.push({ op: 'STORE', arg: addr });
        continue;
      }

      // ARR nums = [...]
      const arrMatch = trimmed.match(/^ARR\s+(\w+)\s*=\s*\[(.*)\]$/);
      if (arrMatch) {
        const [, name, elements] = arrMatch;
        const addr = varAddr++;
