        }
        continue;
      }
    }

    bytecode.push({ op: 'HALT' });
    return { bytecode, variables };
  }
}

// Runtime (실행)
class SimpleRuntime {
  execute(bytecode) {
    const stack = [];
    const variables = new Map();
    const output = [];

    for (const instr of bytecode) {
      switch (instr.op) {
        case 'PUSH':
          stack.push(instr.arg);
          break;

        case 'POP':
          stack.pop();
          break;

        case 'LOAD':
          stack.push(variables.get(instr.arg));
          break;

        case 'STORE':
          variables.set(instr.arg, stack.pop());
          break;

        case 'ADD': {
          const b = stack.pop();
          const a = stack.pop();
          stack.push(a + b);
          break;
        }

        case 'SUB': {
          const b = stack.pop();
          const a = stack.pop();
          stack.push(a - b);
          break;
        }

        case 'MUL': {
          const b = stack.pop();
          const a = stack.pop();
          stack.push(a * b);
          break;
        }

        case 'ARR_NEW': {
          const size = instr.arg;
          const arr = [];
          for (let i = 0; i < size; i++) {
            arr.unshift(stack.pop());
          }
          stack.push(arr);
          break;
        }

        case 'ARR_SUM': {
          const arr = stack.pop();
          stack.push(arr.reduce((a, b) => a + b, 0));
          break;
        }

        case 'ARR_AVG': {
          const arr = stack.pop();
          stack.push(arr.length > 0 ? arr.reduce((a, b) => a + b, 0) / arr.length : 0);
          break;
        }

        case 'CALL':
          if (instr.arg === -1) {
            // println
            const arg = stack.pop();
            output.push(String(arg));
          }
          break;

        case 'HALT':
          break;
      }
    }

    return {
      output: output.join('\n'),
      stack: stack.length > 0 ? stack[stack.length - 1] : null,
    };
  }
}

