function test(name, code, expected) {
  console.log(`\n📍 테스트: ${name}`);
  console.log('─'.repeat(40));
  console.log('코드:');
  console.log(code);
  console.log('');

  try {
    const gen = new SimpleBytecodeGen();
    const { bytecode } = gen.generate(code);

    console.log('Bytecode:');
    for (const instr of bytecode) {
      if (instr.arg !== undefined) {
        console.log(`  ${instr.op} ${instr.arg}`);
      } else {
        console.log(`  ${instr.op}`);
      }
    }
    console.log('');

    const runtime = new SimpleRuntime();
    const result = runtime.execute(bytecode);

    console.log('출력:');
    console.log(result.output || '(없음)');

    if (expected && result.output.includes(String(expected))) {
      console.log(`✅ PASS (기대값: ${expected})`);
    } else if (expected) {
      console.log(`❌ FAIL (기대값: ${expected})`);
    }
  } catch (error) {
    console.log(`❌ 오류: ${error.message}`);
  }
}

